/**
 * Renames, enables or disables a recipient. The last enabled recipient cannot be disabled while Hyok is allowed. Administrator only.
 */
export const updateRecipient = async (
  organization: string,
  project: string,
  id: string,
  clientEncryptionRecipientUpdate: ClientEncryptionRecipientUpdate,
  options?: Parameters<typeof storytellerFetch>[1],
): Promise<ClientEncryptionRecipient> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return storytellerFetch<ClientEncryptionRecipient>(
    getUpdateRecipientUrl(organization, project, id),
    {
      ...options,
      method: "PATCH",
      headers: {
        "Content-Type": "application/json",
        ...getHeaders(options?.headers),
      },
      body: JSON.stringify(clientEncryptionRecipientUpdate),
    },
  );
};

